import{_ as o,o as e,c as a,ah as r}from"./chunks/framework.eLu1Yovf.js";const n="/projects/uHand_UNO/en/latest/assets/image2.B6CtJXWO.webp",i="/projects/uHand_UNO/en/latest/assets/image3.3kruD5hh.webp",s="/projects/uHand_UNO/en/latest/assets/image4.DZRSiHO0.webp",d="/projects/uHand_UNO/en/latest/assets/image5.Cq_YmDDI.webp",l="data:image/png;base64,",c="data:image/png;base64,",A="data:image/png;base64,",u="/projects/uHand_UNO/en/latest/assets/image9.DubWYp_b.webp",h="/projects/uHand_UNO/en/latest/assets/image10.w-bnCVin.webp",p="/projects/uHand_UNO/en/latest/assets/image2.4zZa-Fjt.webp",q=JSON.parse('{"title":"3. Default Program Download Instruction","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3.Default_Program_Download.md","filePath":"docs/3.Default_Program_Download.md"}'),g={name:"docs/3.Default_Program_Download.md"};function m(w,t,b,f,I,O){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="_3-default-program-download-instruction" tabindex="-1">3. Default Program Download Instruction <a class="header-anchor" href="#_3-default-program-download-instruction" aria-label="Permalink to &quot;3. Default Program Download Instruction&quot;">​</a></h1><p>The firmware program is not flashed by default, which includes basic game functions such as &quot;<strong>knob control</strong>&quot; and &quot;<strong>APP control</strong>&quot;.</p><h2 id="_3-1-getting-ready" tabindex="-1">3.1 Getting Ready <a class="header-anchor" href="#_3-1-getting-ready" aria-label="Permalink to &quot;3.1 Getting Ready&quot;">​</a></h2><p>Follow the instructions in &quot;<a href="https://docs.hiwonder.com/projects/uHand_UNO/en/latest/docs/2.Set_Arduino_Environment.html#arduino-ide-instruction" target="_blank" rel="noreferrer"><strong>2. Set Arduino Environment\\2.2 Arduino IDE Instruction</strong></a>&quot; to import the <strong><a href="../_static/source_code/FastLED-master.zip">FastLED-master.zip</a></strong> library file into the Arduino IDE. If the FastLED-master.zip library file has already been imported before, you can skip this step.</p><img loading="lazy" height="73" width="414" class="common_img" src="'+n+'"><h2 id="_3-2-program-download" tabindex="-1">3.2 Program Download <a class="header-anchor" href="#_3-2-program-download" aria-label="Permalink to &quot;3.2  Program Download&quot;">​</a></h2><p><a href="../_static/source_code/uhand.zip">uHand</a></p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p>Remove the Bluetooth module before downloading the program. Or the program will fail to download because of the serial port conflict.</p></li><li><p>Please switch the battery box to the &#39;OFF&#39; when connecting the Type-B download cable. This action prevents the download cable from accidentally touching the power pins of the expansion board, which may cause a short circuit.</p></li></ul></div><p>(1) Locate and open <strong>&quot;uhand/uhand.ino&quot;</strong> program file .</p><img loading="lazy" height="123" width="682" class="common_img" src="'+i+'"><p>(2) Connect Arduino to the computer with the UNO data cable (Type-B) .</p><img loading="lazy" height="725" width="1039" class="common_img" src="'+s+'"><p>(3) Click <strong>&quot;Select Board&quot;</strong>, and the software will automatically detect the current Arduino serial port. Next, click to connect.</p><img loading="lazy" height="213" width="658" class="common_img" src="'+d+'"><p>(3) Click<img loading="lazy" height="49" width="48" class="common_img" src="'+l+'"> to download the program into Arduino. Then just wait for it to complete.</p><img loading="lazy" height="39" width="655" class="common_img" src="'+c+'" style="width:556px;"><img loading="lazy" height="41" width="499" class="common_img" src="'+A+'" style="width:556px;"><h2 id="_3-3-program-outcome" tabindex="-1">3.3 Program Outcome <a class="header-anchor" href="#_3-3-program-outcome" aria-label="Permalink to &quot;3.3  Program Outcome&quot;">​</a></h2><p>(1) When powered on, the robotic hand will return to the neutral position. Its five fingers spread out, and the RGB light on the expansion board turns white. This is the neutral position program.</p><img loading="lazy" height="768" width="986" class="common_img" src="'+u+'"><p>(3) Simultaneously press two buttons for one second. When the RGB light turns green, the neutral position function will be unlocked, and the knob control mode will be activated.</p><img loading="lazy" height="736" width="945" class="common_img" src="'+h+'"><p>(4) Pressing K1 will first clear the previous action group and enter the action group editing mode. Then, use the knob to control the posture of the robotic hand, and press K1 to record the current posture into the action group. Press K1 to exit the action group editing mode and save the edited action group to Flash. Next, simply press K2 to execute the action group.</p><p>The button functions are described below:</p><table class="docutils-nobg" style="margin:0 auto;" border="1"><thead><tr><th>Mode</th><th>Button</th><th>Display</th></tr></thead><tbody><tr><td>Neutral Position Mode</td><td>Automatically enter the mode after powered on, at the same time long press &quot;K1, K2&quot; to exit</td><td>ID1-6 servos are at 90 °.</td></tr><tr><td rowspan="3">Normal mode (green light is steady on)</td><td>Long press the red &quot;K1&quot;.</td><td>Enter the editing action group mode to clear the original action group.</td></tr><tr><td>Short press the yellow &quot;K2&quot;.</td><td>Enter the running action group mode to run the saved action group once.</td></tr><tr><td>Long press the yellow &quot;K2&quot;.</td><td>Enter the running action group mode and loop run the saved action group.</td></tr><tr><td rowspan="2">Editing action group mode (red light is steady on)</td><td>Short press the red &quot;K1&quot;.</td><td>Save action.</td></tr><tr><td>Long press the red &quot;K1&quot;.</td><td>Save the editing action group and exit to switch to the normal mode.</td></tr><tr><td>Running action group mode (yellow light is steady on)</td><td>Short press the red &quot;K1&quot;.</td><td>Stop the running action group and switch to the normal mode.</td></tr></tbody></table><p>(5) Upon inserting the Bluetooth module and connecting to the app, the Bluetooth control game will be activated.</p><img loading="lazy" height="915" width="1267" class="common_img" src="'+p+'">',27)])])}const E=o(g,[["render",m]]);export{q as __pageData,E as default};
